/* Local view state is separate from creative content and never enters undo history. */
var ViewSession={restoring:true,timer:0,
 read(key){let value;try{value=JSON.parse(localStorage.getItem(key+'.view'))}catch{}if(!value||typeof value!=='object')return{};const result={};if(['structure','whiteboard','shots','overview'].includes(value.tab))result.tab=value.tab;for(const key of ['activeBoard','shotContentId','shotHistoryId','selectedTopic'])if(typeof value[key]==='string')result[key]=value[key];result.shotMode=value.shotMode==='history'?'history':'active';if(/^\d{4}-\d{2}-01$/.test(value.month||''))result.month=value.month;for(const key of ['camera','contentCamera']){const c=value[key];if(c&&[c.x,c.y,c.z].every(Number.isFinite)&&c.z>=.05&&c.z<=8)result[key]=c}if(value.scroll&&typeof value.scroll==='object')result.scroll=value.scroll;return result;},
 write(){try{const scroll={};for(const [name,selector]of Object.entries({dates:'#dateList',shots:'#shotsBody',calendar:'#overviewView .agenda-wrap'})){const el=$(selector);if(el)scroll[name]=el.scrollTop}localStorage.setItem(STORE+'.view',JSON.stringify({tab,activeBoard:state.activeBoard,shotContentId,shotMode,shotHistoryId,selectedTopic,month:localDate(month),camera:{...pan,z:zoom},contentCamera:{...topicPan,z:ContentCamera.zoom},scroll}))}catch{}},
 remember(){if(this.restoring)return;clearTimeout(this.timer);this.timer=setTimeout(()=>this.write(),120)},
 restoreScroll(value){for(const [name,selector]of Object.entries({dates:'#dateList',shots:'#shotsBody',calendar:'#overviewView .agenda-wrap'})){const el=$(selector),top=value?.[name];if(el&&Number.isFinite(top))el.scrollTop=Math.max(0,top)}}
};
